        { instrument: 'kick', notes: [36, 48], velocity: 100, durationMs: 600 }, // Kick (Beat 1, 3)
        { instrument: 'snare', notes: [38], velocity: 120, durationMs: 1000 }, // Snare (Beat 2, 4)
