            setTimeout(() => {
                plays.forEach(p => p.stop()); // Stop lingering audio if needed, though playNote tries to manage duration
                resolve();
            }, durationMs + 500); // Allow some buffer time
        });
    }

    function playBassLine(bassNotes, durationMs) {
        const startTime = performance.now();
        for (const note of bassNotes) {
            playMidiNote(note, 100, durationMs / 2); // Shorter notes for bass movement
            // Introduce a small delay to simulate timing flow
            // In a real system, this would be synced via MIDI time.
            const delay = (note === bassNotes[0] && bassNotes.length > 1) ? 500 : 100; 
            setTimeout(() => {
                 // This is a crude simulation of timing; real timing requires precise synchronization
            }, delay);
        }
    }

    function playDrums(pattern, durationMs) {
        const startTime = performance.now();
        for (const drum of pattern) {
            if (drum.notes.length > 0) {
                const plays = drum.notes.map(note => playMidiNote(note, drum.velocity, drum.durationMs));
                // In a real loop, these plays would be scheduled precisely based on the beat.
                plays.forEach(p => p.stop());
            }
        }
    }

    function loopMusic() {
        if (!isPlaying) return;

        status.textContent = "Status: Music Loop Running...";

        // 1. Play G Major Chord (Whole Measure)
        playChord(G_MAJOR_NOTES, MEASURE_LENGTH);

        // 2. Play Walking Bass Line (Whole Measure)
        playBassLine(BASS_NOTES, MEASURE_LENGTH);

        // 3. Play Boom-Chuck Drums (Whole Measure)
        playDrums(DRUM_PATTERN, MEASURE_LENGTH);

        // Schedule the next loop iteration
        const loopDuration = MEASURE_LENGTH;
        const loopTime = performance.now();

        animationId = setInterval(() => {
            // Since we play the whole piece in one block, we just reset the status visualization here
            // In a continuous loop, we'd manage the timing manually within the interval or use precise scheduling.
        }, loopDuration);
    }

    // --- Event Handlers ---

    startButton.addEventListener('click', async () => {
        if (!isPlaying) {
            initializeAudio().then(() => {
                isPlaying = true;
                startButton.disabled = true;
                stopButton.disabled = false;
                status.textContent = "Status: Starting music loop...";
                loopMusic();
            });
        }
    });

    stopButton.addEventListener('click', () => {
        isPlaying = false;
        if (animationId) {
            clearInterval(animationId);
            animationId = null;
        }
        startButton.disabled = false;
        stopButton.disabled = true;
        status.textContent = "Status: Music loop stopped. Ready to start again.";
    });

    status.textContent = "Status: Ready. Click Start to begin.";

