const bpm = 120;
const beat = 60000 / bpm;
let start = performance.now();

function playWalkingBassLine() {
    const bassNotes = ['G2', 'A2', 'G2', 'B2'];
    const bassDuration = 0.5;
    const bassTime = start + 0;

    bassNotes.forEach((note, index) => {
        setTimeout(() => {
            out.send({ instrument: 'bass', notes: `Walking Bass Line: ${note}`, loudness: 75, duration: bassDuration, time: bassTime + index * bassDuration * 1.2 });
        }, 0);
    });
}

function playBoomChuck() {
    const drumPattern = [
        { type: 'kick', time: start + 0 },
        { type: 'snare', time: start + 0.5 },
        { type: 'kick', time: start + 1 },
        { type: 'snare', time: start + 1.5 }
    ];

    drumPattern.forEach(hit => {
        setTimeout(() => {
            out.send({ instrument: 'drums', notes: `Drum Hit: ${hit.type}`, loudness: 90, duration: 0.1, time: hit.time });
        }, 0);
    });
}

function playChord() {
    out.send({ instrument: 'piano', notes: 'G major', loudness: 90, duration: 1.0, time: start });
}

setInterval(() => {
    playChord();

    if (start % (beat * 2) < beat * 0.5) {
        playWalkingBassLine();
    }

    playBoomChuck();

    start += beat;
}, beat);

console.log("Music loop started.");
